// Generates overlay/src/renderer/ws/protocol.gen.ts from protocol/messages.schema.json.
// The generated file is never edited by hand: rerun `pnpm gen:protocol`.
import { readFile, writeFile } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { compile } from 'json-schema-to-typescript'

const here = dirname(fileURLToPath(import.meta.url))
const schemaPath = resolve(here, '../../protocol/messages.schema.json')
const outPath = resolve(here, '../src/renderer/ws/protocol.gen.ts')

const schema = JSON.parse(await readFile(schemaPath, 'utf8'))
const messages = schema['x-messages']

// One interface per $defs entry, plus a discriminated union of every message.
const defs = schema.$defs
const root = {
  $schema: schema.$schema,
  title: 'ProtocolRoot',
  type: 'object',
  properties: Object.fromEntries(Object.keys(defs).map((name) => [name, { $ref: `#/$defs/${name}` }])),
  required: [],
  additionalProperties: false,
  $defs: defs
}

let ts = await compile(root, 'ProtocolRoot', {
  bannerComment: '',
  additionalProperties: false,
  unreachableDefinitions: true,
  declareExternallyReferenced: true,
  format: false
})

const typeNames = Object.keys(messages)
const pascal = (s) => s.replace(/(^|_)(\w)/g, (_, __, c) => c.toUpperCase())
// A payload def that is just a $ref (e.g. payload_auto_refresh -> Empty) is emitted under the target's name.
const payloadTypeName = (t) => {
  const ref = defs['payload_' + t].$ref
  return ref ? pascal(ref.split('/').pop()) : pascal('payload_' + t)
}
const lines = []
lines.push('// GENERATED by overlay/scripts/gen-protocol.mjs from protocol/messages.schema.json. Do not edit.')
lines.push('/* eslint-disable */')
lines.push(ts.replace(/export interface ProtocolRoot \{[\s\S]*?\n\}\n/, ''))
lines.push('export type Direction = "o2a" | "a2o"')
lines.push(`export const MESSAGE_DIRECTIONS = ${JSON.stringify(messages, null, 2)} as const`)
lines.push('export type MessageType = keyof typeof MESSAGE_DIRECTIONS')
lines.push('export interface PayloadMap {')
for (const t of typeNames) lines.push(`  ${t}: ${payloadTypeName(t)}`)
lines.push('}')
lines.push('export type Message<T extends MessageType = MessageType> = {')
lines.push('  [K in T]: Omit<Envelope, "type" | "payload"> & { type: K; payload: PayloadMap[K] }')
lines.push('}[T]')
lines.push(`export type OverlayToAgent = Message<${typeNames.filter((t) => messages[t] === 'o2a').map((t) => JSON.stringify(t)).join(' | ')}>`)
lines.push(`export type AgentToOverlay = Message<${typeNames.filter((t) => messages[t] === 'a2o').map((t) => JSON.stringify(t)).join(' | ')}>`)
await writeFile(outPath, lines.join('\n') + '\n')
console.log(`wrote ${outPath}`)
